DROP TABLE IF EXISTS `livres_livre`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `livres_livre` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `titre` varchar(500) NOT NULL,
  `auteur` varchar(500) NOT NULL,
  `isbn` varchar(50) NOT NULL,
  `date_publication` date NOT NULL,
  `couverture` varchar(100) DEFAULT NULL,
  `categorie_id` bigint DEFAULT NULL,
  `resume` longtext NOT NULL,
  `lecture_en_ligne` varchar(200) DEFAULT NULL,
  `quantite` int unsigned NOT NULL,
  `date_ajout_livre` date NOT NULL,
  `est_nouveau` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `isbn` (`isbn`),
  KEY `livres_livre_categorie_id_f7d687f2_fk_livres_categorie_id` (`categorie_id`),
  CONSTRAINT `livres_livre_categorie_id_f7d687f2_fk_livres_categorie_id` FOREIGN KEY (`categorie_id`) REFERENCES `livres_categorie` (`id`),
  CONSTRAINT `livres_livre_chk_1` CHECK ((`quantite` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
